   100	get_pool_block_size(mrb_state *mrb, const mrb_irep *irep)
   101	{
   102	  int pool_no;
   103	  size_t size = 0;
   104	
   105	  size += sizeof(uint16_t); /* plen */
   106	  size += irep->plen * sizeof(uint8_t); /* len(n) */
   107	
   108	  for (pool_no = 0; pool_no < irep->plen; pool_no++) {
   109	    int ai = mrb_gc_arena_save(mrb);
   110	
   111	    switch (irep->pool[pool_no].tt) {
   112	    case IREP_TT_INT64:
   113	#if defined(MRB_64BIT) || defined(MRB_INT64)
   114	      {
   115	        int64_t i = irep->pool[pool_no].u.i64;
   116	
   117	        if (i < INT32_MIN || INT32_MAX < i)
   118	          size += 8;
   119	        else
   120	          size += 4;
   121	      }
   122	      break;
   123	#else
   124	      /* fall through */
   125	#endif
   126	    case IREP_TT_INT32:
   127	      size += 4;                /* 32bits = 4bytes */
   128	      break;
   129	
   130	    case IREP_TT_BIGINT:
   131	      {
   132	        mrb_int len = irep->pool[pool_no].u.str[0];
   133	        mrb_assert_int_fit(mrb_int, len, size_t, SIZE_MAX);
   134	        size += (size_t)len+2;
   135	      }
   136	      break;
   137	
   138	    case IREP_TT_FLOAT:
   139	#ifndef MRB_NO_FLOAT
   140	      {
   141	        size += sizeof(double);
   142	      }
   143	#endif
   144	      break;
   145	
   146	    default: /*  packed IREP_TT_STRING */
   147	      {
   148	        mrb_int len = irep->pool[pool_no].tt >> 2; /* unpack length */
   149	        mrb_assert_int_fit(mrb_int, len, size_t, SIZE_MAX);
   150	        size += sizeof(uint16_t);
   151	        size += (size_t)len+1;
   152	      }
   153	      break;
   154	    }
   155	    mrb_gc_arena_restore(mrb, ai);
   156	  }
   157	
   158	  return size;
   159	}
